-- local query = teamyar.query(context,[[{"query":"with recursive CTE_Account AS (SELECT ID as SourceAccount,ID as AccountID, CODE AS AccountCode, PARENT , ORG_ID AS ORG_ID FROM pa_account WHERE ORG_ID = 2 UNION SELECT  CTE_Account.SourceAccount as SourceAccount,pa.ID as AccountID, pa.CODE AS AccountCode, pa.PARENT , pa.ORG_ID AS ORG_ID FROM CTE_Account INNER JOIN pa_account as pa ON CTE_Account.AccountID = pa.PARENT and CTE_Account.ORG_ID = pa.ORG_ID), CTE_DateRangePerYear as (select min(JNDATE) as MinJndate,max(JNDATE) as MaxJndate,min(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) as sdate,  max(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) edate, JYEAR FROM REPORT_DIMDATE where (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) group by JYEAR), CTE_VoucherRecords as  (select cte_DateRangePerYear.MaxJndate as MaxJndate,JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,SUM(COALESCE(pvr.CRD, 0) - COALESCE(pvr.DEB, 0)) as remain from cte_DateRangePerYear inner join pa_voucher as pv on pv.RUN_DATE >= sdate and pv.RUN_DATE <= edate inner join pa_voucher_record as pvr on pv.ID = pvr.VOUCHER_ID and pv.ORG_ID = pvr.ORG_ID where pv.ORG_ID = 2 and (pv.RUN_DATE >=132922818000000000 and pv.RUN_DATE <= 133552800000000000) /*and pv.type in (1,4,5) and pv.status in(2,4,5,6)*/ and pv.deleted = 0 and pvr.deleted = 0 group by cte_DateRangePerYear.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID) , CTE_MinDateRange AS (SELECT min(MinJndate) as MinJndate,min(JYEAR) as JYEAR,min(sdate) sdate ,min(edate) edate FROM cte_DateRangePerYear) , CTE_OpeningVoucherRecords as  (select CTE_MinDateRange.MinJndate,JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,SUM(COALESCE(pvr.CRD, 0) - COALESCE(pvr.DEB, 0)) as remain from CTE_MinDateRange inner join pa_voucher as pv on pv.RUN_DATE >= sdate and pv.RUN_DATE <= edate inner join pa_voucher_record as pvr on pv.ID = pvr.VOUCHER_ID and pv.ORG_ID = pvr.ORG_ID where pv.ORG_ID = 2 and (pv.RUN_DATE >=132922818000000000 and pv.RUN_DATE <= 133552800000000000) and pv.type=12 and pv.status in(2,4,5,6) and pv.deleted = 0 and pvr.deleted = 0 group by CTE_MinDateRange.MinJndate,JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID) ,CTE_AccountsVouchers AS (select CTE_Account.SourceAccount,CTE_Account.ORG_ID,sum(CTE_VoucherRecords.remain) as remain,CTE_VoucherRecords.JYEAR,MaxJndate as Jndate from CTE_Account left join CTE_VoucherRecords on CTE_Account.AccountID=CTE_VoucherRecords.ACCOUNT_ID and CTE_Account.ORG_ID=CTE_VoucherRecords.ORG_ID group by CTE_Account.SourceAccount,CTE_Account.ORG_ID,CTE_VoucherRecords.JYEAR,Jndate),CTE_AccountsVouchersInfo AS (select SourceAccount, ORG_ID, remain, Jndate, JYEAR from CTE_AccountsVouchers UNION All select ACCOUNT_ID,ORG_ID,remain,MinJndate,JYEAR from CTE_OpeningVoucherRecords), CTE_NotCurrTangibleFixedAssets_T3 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 3 as type from CTE_AccountsVouchersInfo where SourceAccount in(2605) group by ORG_ID,JYEAR,Jndate), CTE_TCOPIncomeAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 2 as type from CTE_AccountsVouchersInfo where SourceAccount in(1663,1244) group by ORG_ID,JYEAR,Jndate) ,CTE_NotCurrInvestmentInRealState_T4 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 4 as type from CTE_AccountsVouchersInfo where SourceAccount in(1246) group by ORG_ID,JYEAR,Jndate), CTE_NotCurrInvisibleAssets_T5 as(select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 5 as type from CTE_AccountsVouchersInfo where SourceAccount in(1644) group by ORG_ID,JYEAR,Jndate), CTE_NotCurrLongTimeInvestments_T6 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 6 as type from CTE_AccountsVouchersInfo where SourceAccount in(1850) group by ORG_ID,JYEAR,Jndate), CTE_NotCurrLongTermReceivables_T7 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 7 as type from CTE_AccountsVouchersInfo where SourceAccount in(1190) group by ORG_ID,JYEAR,Jndate), CTE_NotCurTransferTaxAsset_T8 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 8 as type from CTE_AccountsVouchersInfo where SourceAccount in(1696) group by ORG_ID,JYEAR,Jndate), CTE_NotCurrOtherAssets_T9 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 9 as type from CTE_AccountsVouchersInfo where SourceAccount in(1681) group by ORG_ID,JYEAR,Jndate), CTE_CurrPrePaids_T12 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 12 as type from CTE_AccountsVouchersInfo where SourceAccount in(1648) group by ORG_ID,JYEAR,Jndate), CTE_CurrInventories_T13 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 13 as type from CTE_AccountsVouchersInfo where SourceAccount in(1663) group by ORG_ID,JYEAR,Jndate), CTE_CurrCommercialAndOtherReceivables_T14 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 14 as type from CTE_AccountsVouchersInfo where SourceAccount in(1630) group by ORG_ID,JYEAR,Jndate), CTE_CurrShortTermInvestments_T15 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 15 as type from CTE_AccountsVouchersInfo where SourceAccount in(1651,2174,1663,1630) group by ORG_ID,JYEAR,Jndate), CTE_CurrCashBalance_T16 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 16 as type from CTE_AccountsVouchersInfo where SourceAccount in(1663,2160,1630) group by ORG_ID,JYEAR,Jndate), CTE_CurrNonCommercialAssetsForSale_T18 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 18 as type from CTE_AccountsVouchersInfo where SourceAccount in(2022) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightFund_T23 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 23 as type from CTE_AccountsVouchersInfo where SourceAccount in(1252) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightCapitalIncreaseInFlow_T24 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 24 as type from CTE_AccountsVouchersInfo where SourceAccount in(6063) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightSpendOnShares_T25 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 25 as type from CTE_AccountsVouchersInfo where SourceAccount in(1617) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightSpendingOnTeasuryShares_T26 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 26 as type from CTE_AccountsVouchersInfo where SourceAccount in(1617) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightLegalReserve_T27 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 27 as type from CTE_AccountsVouchersInfo where SourceAccount in(1255,1611) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightOtherReserves_T28 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 28 as type from CTE_AccountsVouchersInfo where SourceAccount in(1255,1611) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightAssetRevaluationSurplus_T29 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 29 as type from CTE_AccountsVouchersInfo where SourceAccount in(2605) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightAccumulatedProfit_T30 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 30 as type from CTE_AccountsVouchersInfo where SourceAccount in(2124) group by ORG_ID,JYEAR,Jndate), CTE_OwnerRightTreasurayShares_T31 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 31 as type from CTE_AccountsVouchersInfo where SourceAccount in(1253) group by ORG_ID,JYEAR,Jndate), CTE_NonCurrLongTermPayables_T36 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 36 as type from CTE_AccountsVouchersInfo where SourceAccount in(2031) group by ORG_ID,JYEAR,Jndate), CTE_NonCurrLongTermFacilities_T37 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 37 as type from CTE_AccountsVouchersInfo where SourceAccount in(2035) group by ORG_ID,JYEAR,Jndate), CTE_NonCurrTransferTaxDebt_T38 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 38 as type from CTE_AccountsVouchersInfo where SourceAccount in(1245) group by ORG_ID,JYEAR,Jndate), CTE_NonCurrSaveMilitaryServicesBenefits_T39 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 39 as type from CTE_AccountsVouchersInfo where SourceAccount in(2036,2251,2252,2607,2620,2660) group by ORG_ID,JYEAR,Jndate), CTE_CurrCommercialAndOtherPayables_T42 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 42 as type from CTE_AccountsVouchersInfo where SourceAccount in(1758) group by ORG_ID,JYEAR,Jndate), CTE_CurrTaxPayable_T43 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 43 as type from CTE_AccountsVouchersInfo where SourceAccount in(1704) group by ORG_ID,JYEAR,Jndate), CTE_CurrDividendsPayable_T44 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 44 as type from CTE_AccountsVouchersInfo where SourceAccount in(1796) group by ORG_ID,JYEAR,Jndate), CTE_CurrFinancialFacilities_T45 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 45 as type from CTE_AccountsVouchersInfo where SourceAccount in(1797) group by ORG_ID,JYEAR,Jndate), CTE_CurrResources_T46 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 46 as type from CTE_AccountsVouchersInfo where SourceAccount in(1800) group by ORG_ID,JYEAR,Jndate), CTE_CurrPrepayments_T47 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 47 as type from CTE_AccountsVouchersInfo where SourceAccount in(1789) group by ORG_ID,JYEAR,Jndate), CTE_NonCurrAssetsLiablitiesForSale_T49 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 49 as type from CTE_AccountsVouchersInfo where SourceAccount in(1390) group by ORG_ID,JYEAR,Jndate), cte_UnionRemainAccounts AS(SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NotCurrTangibleFixedAssets_T3 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NotCurrInvestmentInRealState_T4 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NotCurrInvisibleAssets_T5  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NotCurrLongTimeInvestments_T6 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NotCurrLongTermReceivables_T7  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NotCurTransferTaxAsset_T8 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NotCurrOtherAssets_T9  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrPrePaids_T12  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrInventories_T13  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrCommercialAndOtherReceivables_T14 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrShortTermInvestments_T15 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrCashBalance_T16 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrNonCommercialAssetsForSale_T18  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightFund_T23  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightCapitalIncreaseInFlow_T24  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightSpendOnShares_T25 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightSpendingOnTeasuryShares_T26  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightLegalReserve_T27  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightOtherReserves_T28 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightAssetRevaluationSurplus_T29 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightAccumulatedProfit_T30  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_OwnerRightTreasurayShares_T31 UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NonCurrLongTermPayables_T36  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NonCurrLongTermFacilities_T37  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NonCurrTransferTaxDebt_T38  UNION All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NonCurrSaveMilitaryServicesBenefits_T39  Union All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrCommercialAndOtherPayables_T42 Union All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrTaxPayable_T43  Union All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrDividendsPayable_T44 Union All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrFinancialFacilities_T45  Union All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrResources_T46  Union All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_CurrPrepayments_T47  Union All SELECT  ORG_ID, remain, JYEAR, type,Jndate FROM CTE_NonCurrAssetsLiablitiesForSale_T49), CTE_SumNonCurrentAssets_T10 as (select  ORG_ID, sum(remain) as remain, JYEAR, 10 as type,Jndate from cte_UnionRemainAccounts where type>=3 and type<=9 group by ORG_ID, JYEAR,Jndate) , CTE_NoName_T17 as (select  ORG_ID, sum(remain) as remain, JYEAR, 17 as type,Jndate from cte_UnionRemainAccounts where type>= 12 And type <= 16 group by ORG_ID, JYEAR,Jndate), CTE_SumCurrentAssets_T19 as (select  ORG_ID, sum(remain) as remain, JYEAR, 19 as type,Jndate from cte_UnionRemainAccounts where type>= 12 And type <= 18 group by  ORG_ID, JYEAR,Jndate), CTE_SumAssets_T20 as (select  ORG_ID, sum(remain) as remain, JYEAR, 20 as type,Jndate from cte_UnionRemainAccounts where type>=3 and type<=18 group by ORG_ID, JYEAR,Jndate), CTE_SumOwnerRights_T32 as (select  ORG_ID, sum(remain) as remain, JYEAR, 32 as type,Jndate from cte_UnionRemainAccounts where type>=23 and type<=31 group by ORG_ID, JYEAR,Jndate), CTE_SumNonCurrentLiabilities_T40 as (select  ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 40 as type,Jndate from cte_UnionRemainAccounts where type>= 36 and type<= 39 group by  ORG_ID, JYEAR,Jndate), CTE_NoName_T48 as (select  ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 48 as type,Jndate from cte_UnionRemainAccounts where type>=42 and type<=47 group by  ORG_ID, JYEAR,Jndate), cte_SumCurrentLiabilities_T50 as ( select  ORG_ID,sum(COALESCE(remain,0)) as remain,JYEAR, 50 as type,Jndate from  cte_UnionRemainAccounts where type>=42 and type<=49 group by  ORG_ID, JYEAR,Jndate), CTE_SumDebts_T51 as (select  ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 51 as type,Jndate from cte_UnionRemainAccounts where type>= 36 and type<= 49 group by  ORG_ID, JYEAR,Jndate), CTE_SumOwnerRightsAndDebts_T52 as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 52 as type,Jndate from cte_UnionRemainAccounts  group by  ORG_ID, JYEAR,Jndate), cte_DecimalCount as (select ps.ORG_ID,ps.ID,ps.name,ps.DECIMAL_COUNT,ps.FEE_DECIMAL from PA_ORGANIZATIONS as po inner join PA_SYMBOLS as ps on po.BASE_CURRENCY = ps.id and po.ORG_ID = ps.ORG_ID), CTE_RemainAccounts AS(SELECT  ORG_ID, REMAIN , JYEAR, TYPE,Jndate FROM CTE_UnionRemainAccounts UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_SumNonCurrentAssets_T10 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_NoName_T17 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_SumCurrentAssets_T19 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_SumAssets_T20 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_SumAssets_T20 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_SumNonCurrentLiabilities_T40 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_NoName_T48 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_SumCurrentLiabilities_T50 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_SumDebts_T51 UNION ALL SELECT  ORG_ID, remain , JYEAR, TYPE ,Jndate FROM  CTE_SumOwnerRightsAndDebts_T52), Cte_RemainAccountsBaseDecimalCount as (select cra.ORG_ID,oi.NAME as OrgName,  COALESCE(cra.remain, 0)/POWER(10, COALESCE(cdc.DECIMAL_COUNT, 0)) as remain , cra.JYEAR, cra.type,cra.Jndate  from Cte_RemainAccounts cra left join cte_DecimalCount cdc on cra.ORG_ID = cdc.ORG_ID left join org_info oi on cra.ORG_ID = oi.ID) SELECT JSON_ARRAYAGG(JSON_OBJECT( 'ORG_ID',ORG_ID, 'OrgName',OrgName,'type',type,'JYEAR',JYEAR,'Jndate',Jndate,'remain',remain, 'title',CASE COALESCE(type,0) WHEN 3 THEN 'دارایی های ثابت مشهود' WHEN 4 THEN 'سرمایه گذاری در املاک' WHEN 5 THEN 'دارایی های نامشهود' WHEN 6 THEN 'سرمایه گذاری های بلند مدت' WHEN 7 THEN 'دریافتنی های بلند مدت'  WHEN 8 THEN 'دارایی مالیات انتقالی' WHEN 9 THEN 'سایر دارایی ها' WHEN 10 THEN 'جمع دارایی های غیر جاری' WHEN 12 THEN 'پیش پرداخت ها' WHEN 13 THEN 'موجودی مواد و کالا'  WHEN 14 THEN 'ریافتنی های تجاری و سایر دریافتنی ها' WHEN 15 THEN 'سرمایه گذاری های کوتاه مدت' WHEN 16 THEN 'موجودی نقد' WHEN 17 THEN '' WHEN 18 THEN 'دارایی های غیر تجاری نگهداری شده برای فروش' WHEN 19 THEN 'جمع دارایی های  جاری'  WHEN 20 THEN 'جمع دارایی ها' WHEN 23 THEN 'سرمایه'  WHEN 24 THEN 'افزایش سرمایه در جریان'  WHEN 25 THEN 'صرف سهام'  WHEN 26 THEN 'صرف سهام خزانه'  WHEN 27 THEN 'اندوخته قانونی'  WHEN 28 THEN 'سایر اندوخته ها '  WHEN 29 THEN 'مازاد تجدید ارزیابی دارایی ها'  WHEN 30 THEN 'سود انباشته'  WHEN 31 THEN 'سهام خزانه'  WHEN 32 THEN 'جمع حقوق مالکانه' WHEN 33 THEN '' WHEN 36 THEN 'پرداختنی های بلند مدت'   WHEN 37 THEN 'تسهیلات مالی بلند مدت'  WHEN 38 THEN 'بدهی مالیات انتقالی'  WHEN 39 THEN 'ذخیره مزایای پایان خدمت کارکنان'  WHEN 40 THEN 'جمع بدهی های غیر جاری' WHEN 42 THEN 'پرداختنی های تجاری و سایر پرداختنی ها'  WHEN 43 THEN 'مالیات پرداختنی'  WHEN 44 THEN 'سود سهام پرداختنی'  WHEN 45 THEN 'تسهیلات مالی'  WHEN 46 THEN 'ذخایر'  WHEN 47 THEN 'پیش دریافت ها'  WHEN 48 THEN ''  WHEN 49 THEN 'بدهی های مرتبط با دارایی های غیر جاری نگهداری شده برای فروش'  WHEN 50 THEN 'جمع بدهی های جاری' WHEN 51 THEN 'جمع بدهی ها'  WHEN 52 THEN 'جمع حقوق مالکانه و بدهی ها' ELSE '--'  END)) as result from Cte_RemainAccountsBaseDecimalCount where Cte_RemainAccountsBaseDecimalCount.JYEAR>=0 order by Cte_RemainAccountsBaseDecimalCount.JYEAR ASC,type;","params":[]}]]);

