function comma_value(amount)
  local formatted = amount
  while true do  
    formatted, k = string.gsub(formatted, "^(-?%d+)(%d%d%d)", '%1,%2')
    if (k==0) then
      break
    end
  end
  return formatted
end

function round(val, decimal)
  if (decimal) then
    return math.floor( (val * 10^decimal) + 0.5) / (10^decimal)
  else
    return math.floor(val+0.5)
  end
end

function format_num(amount, decimal, prefix, neg_prefix)
  local str_amount,  formatted, famount, remain
  decimal = decimal or 2
  neg_prefix = neg_prefix or "-"
  famount = math.abs(round(amount,decimal))
  famount = math.floor(famount)
  remain = round(math.abs(amount) - famount, decimal)
  formatted = comma_value(famount)
  if (decimal > 0) then
    remain = string.sub(tostring(remain),3)
    formatted = formatted .. "." .. remain ..
                string.rep("0", decimal - string.len(remain))
  end
  formatted = (prefix or "") .. formatted 
  if (amount<0) then
    if (neg_prefix=="()") then
      formatted = "("..formatted ..")"
    else
      formatted = neg_prefix .. formatted 
    end
  end
  return formatted
end


local farsiNumbers = {
  [0] = "۰",
  [1] = "۱",
  [2] = "۲",
  [3] = "۳",
  [4] = "۴",
  [5] = "۵",
  [6] = "۶",
  [7] = "۷",
  [8] = "۸",
  [9] = "۹"
}

function convertToFarsi(input)
  local farsiNumber = ""
  local isNegative = false
  if type(input) == "number" then
    if input < 0 then
      isNegative = true
      input = -input
    end
    input = tostring(input)
  elseif type(input) == "string" then
    if input:sub(1, 1) == "-" then
      isNegative = true
      input = input:sub(2)
    end
  else
    return nil
  end
  for i = 1, #input do
    local digit = tonumber(input:sub(i, i))
    if digit ~= nil then
      farsiNumber = farsiNumber .. farsiNumbers[digit]
    else
      farsiNumber = farsiNumber .. input:sub(i, i)
    end
  end
  if isNegative then
    farsiNumber = "(" .. farsiNumber .. ")"
  end
  return farsiNumber
end

